mapper.select:
SELECT id,'comment' AS `recordType`,review_id AS `reviewId`,content,status,created_at AS `createdAt`
FROM review_comment WHERE user_id=#{userId}
UNION ALL
SELECT id,'like',review_id,'',NULL,created_at FROM review_like WHERE user_id=#{userId}
UNION ALL
SELECT id,'helpful_vote',review_id,'',NULL,created_at FROM review_helpful_vote WHERE user_id=#{userId}
UNION ALL
SELECT id,'report',review_id,reason,status,created_at FROM review_report WHERE reporter_user_id=#{userId}
UNION ALL
SELECT id,'comment_report',review_id,reason,status,created_at FROM review_comment_report WHERE reporter_user_id=#{userId}

SELECT id,'comment' AS `recordType`,post_id AS `postId`,content,status,created_at AS `createdAt`
FROM post_comment WHERE user_id=#{userId}
UNION ALL
SELECT id,'like',post_id,'',NULL,created_at FROM post_like WHERE user_id=#{userId}
UNION ALL
SELECT id,'report',post_id,reason,status,created_at FROM post_report WHERE reporter_user_id=#{userId}
UNION ALL
SELECT id,'comment_report',post_id,reason,status,created_at FROM post_comment_report WHERE reporter_user_id=#{userId}

SELECT d.id FROM device_fingerprint d WHERE d.last_user_id=#{userId}
   OR EXISTS(SELECT 1 FROM device_fingerprint_user u WHERE u.region=d.region AND u.fingerprint=d.fingerprint AND u.user_id=#{userId})
ORDER BY d.id FOR UPDATE

mapper.update:
UPDATE conversation SET user_a=CASE WHEN user_a=#{userId} THEN NULL ELSE user_a END,
       user_b=CASE WHEN user_b=#{userId} THEN NULL ELSE user_b END,last_message_preview='',updated_at=CURRENT_TIMESTAMP
WHERE user_a=#{userId} OR user_b=#{userId}

UPDATE reservation SET user_id=0,contact_name='已注销用户',contact_phone='',remark='',
       cancelled_at=CASE WHEN status IN(0,1) THEN CURRENT_TIMESTAMP ELSE cancelled_at END,
       status=CASE WHEN status IN(0,1) THEN 3 ELSE status END,remind_status=3,updated_at=CURRENT_TIMESTAMP WHERE user_id=#{userId}
